package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.kanger.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
/** Actual public selected writer: no IData proxy or default hook change. */
final class ContextSignedWriterMatrix {
 static int checks;static final int WORK=64000000;static final String BAD="!@u left(u)&&right(u)->p(u);",SAFE="!@u left(u)&&right(u)->q(u);";
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean bad=false;try{a.run();}catch(Exception expected){bad=true;}require(bad,why);}
 static void create(Path d,String n,String t)throws Exception{ContextNativeCandidateLeaseMatrix.create(d,n,t);}
 static ContextSignedCandidateInspection.Limits limits(){return ContextSignedCandidateLeaseMatrix.limits();}
 static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}
 static boolean write(Fixture f,String text)throws Exception{return f.db.writeSignedProductionCandidate(f.mind,text,limits(),WORK,WORK,1000000,false);}
 static ContextSignedCommitException refused(Fixture f,String text,ContextSignedCandidateInspection.Limits l,int family,StorageLifecycleErrorCode code)throws Exception{ContextSignedCommitException e=null;try{f.db.writeSignedProductionCandidate(f.mind,text,l,family,WORK,1000000,false);}catch(ContextSignedCommitException error){e=error;}require(e!=null&&e.getErrorCode()==code,"actual public writer typed signed refusal");return e;}
 static void positive(boolean reverse)throws Exception{Path d=Files.createTempDirectory("signed-selected-writer-");create(d,"A","!left(1); !p(1);");create(d,"B","!right(1); !~p(1);");long durable;try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"actual root");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");f.db.saveConnections(f.mind);long before=f.db.getRevision();Set<String> original=primary(f);ContextSignedCommitException conflict=refused(f,BAD,limits(),WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(conflict.getSignedEvidence()!=null&&conflict.getCollisions().isEmpty()&&conflict.getSignedEvidence().getOppositions().stream().anyMatch(o->o.sources.size()==4),"actual full signed four-Source refusal, no old plain collision coercion");conflict.getSignedEvidence().check(WORK,1);require(true,"actual refusal remains independently auditable after rollback");require(f.db.getRevision()==before&&primary(f).equals(original),"selected refusal atomic");require(write(f,SAFE),"actual publication after signed/full-family/legacy gates");require(f.db.getRevision()>before&&primary(f).size()==2&&primary(f).contains(SAFE)&&!primary(f).contains(BAD),"only original safe assertion published");require(f.user.getData()==f.db&&f.user.getCurrentMind()==f.mind,"real provider, no proxy or leaked caller selection");durable=f.db.getRevision();require(f.mind.query("!legacyAfter(9);",null,false),"ordinary follow-up unaffected");require(primary(f).size()==3,"selected attempt does not swallow ordinary follow-up");}try(Fixture f=new Fixture(d,"X")){require(f.db.getRevision()>=durable&&primary(f).size()==3&&primary(f).contains(SAFE)&&!primary(f).contains(BAD),"durable reopen exact originals only");}System.out.println("SIGNED_SELECTED_WRITER_POSITIVE reverse="+reverse+" actualPublicApi=true noProxy=true fullFamilyAndLegacy=true atomicRefusal=true durableReopen=true witnessFreeSuccessOnly=true");}
 static void profile()throws Exception{Path d=Files.createTempDirectory("signed-writer-profile-");create(d,"A","!$u seed(u)&&~blocked(u);");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"actual root");f.db.connectContext("A");long revision=f.db.getRevision();Set<String> original=primary(f);ContextSignedCommitException conflict=refused(f,"!@u seed(u)->blocked(u);",limits(),WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(conflict.getSignedEvidence()!=null&&conflict.getSignedEvidence().getOppositions().stream().anyMatch(o->o.initial&&o.depth==2&&o.sources.size()==2),"actual signed private proof retained by public writer");conflict.getSignedEvidence().check(WORK,1);require(true,"fresh signed evidence audit after refused selected write");StorageLifecycleException incomplete=null;try{write(f,"!@u seed(u)->~blocked(u);");}catch(StorageLifecycleException e){incomplete=e;}require(incomplete!=null&&incomplete.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE,"signed quiescence STILL cannot bypass missing full-family coverage");require((incomplete instanceof ContextSignedCommitException&&((ContextSignedCommitException)incomplete).getPhase().equals("full-family-qualification"))||incomplete instanceof ContextWitnessProductionCommitException,"actual complete-family refusal preserved");require(f.db.getRevision()==revision&&primary(f).equals(original),"signed conflict and missing coverage never publish");require(f.mind.query("!ordinaryAfter(9);",null,false),"ordinary operation remains independent of selected refusal");require(primary(f).size()==2&&f.user.getData()==f.db,"failed selection cleared");}System.out.println("SIGNED_SELECTED_WRITER_PROFILE actualSignedRefusal=true missingSignedFamilyCoverageBlocks=true noDefaultActivation=true");}
 static void trusted()throws Exception{Path d=Files.createTempDirectory("signed-writer-trusted-");create(d,"TR","!$u seed(u)&&~blocked(u);");create(d,"TF","!@u seed(u)->ready(u);");for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(d,"X"+reverse)){require(f.mind.compile("!anchor(1);",null,false),"actual trusted root");f.db.connectContext(reverse?"TF":"TR","own");f.db.connectContext(reverse?"TR":"TF","own");long revision=f.db.getRevision();ContextSignedCommitException conflict=refused(f,"!@u ready(u)->blocked(u);",limits(),WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(conflict.getSignedEvidence()!=null&&conflict.getSignedEvidence().getOppositions().stream().anyMatch(o->"own".equals(o.trustedGroup)&&o.targetContexts.size()==2&&o.sources.size()==3&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==2),"both physical signed TRUST donors retained in one logical cut");conflict.getSignedEvidence().check(WORK,1);require(true,"actual selected trusted proof audits");ContextPendingNativeWrite attempt=f.db.beginSignedProductionWrite(f.mind,limits(),WORK,WORK,1000000);Mind child=null;try{child=new Mind(f.mind);require(child.compile("!@u ready(u)->blocked(u);",null,false),"actual pending child");f.db.applyConnectionCommand(f.mind,"TF","!private(4);");ContextSignedCommitException stale=null;try{attempt.validate(child);}catch(ContextSignedCommitException e){stale=e;}require(stale!=null&&stale.getPhase().equals("owning-attempt")&&stale.getSignedEvidence()==null,"changed initialized physical member invalidates old baseline before proof use");}finally{if(child!=null)f.mind.release(child);f.db.endNativeWrite(attempt);}ContextSignedCommitException fresh=refused(f,"!@u ready(u)->blocked(u);",limits(),WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(fresh.getSignedEvidence()!=null&&f.db.getRevision()==revision&&primary(f).size()==1,"fresh baseline recaptures private member and still rejects real contradiction");}System.out.println("SIGNED_SELECTED_WRITER_TRUSTED orders=2 qualifiedRuntimeAndAllMembers=true initializedViewFreshness=true noFlattening=true noPublication=true");}
 static void ownership()throws Exception{Path d=Files.createTempDirectory("signed-writer-owner-");create(d,"A","!left(1); !p(1);");create(d,"B","!right(1); !~p(1);");long revision;try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"actual root");f.db.connectContext("A");f.db.connectContext("B");revision=f.db.getRevision();ContextPendingNativeWrite attempt=f.db.beginSignedProductionWrite(f.mind,limits(),WORK,WORK,1000000);Mind child=null;try{reject(()->f.db.beginSignedProductionWrite(f.mind,limits(),WORK,WORK,1000000),"nested signed attempt");reject(()->f.db.beginNativeProductionWrite(f.mind,ContextNativeCandidateLeaseMatrix.limits(),WORK,WORK,1000000),"shared selection excludes nested old native attempt");child=new Mind(f.mind);require(child.compile(SAFE,null,false),"actual safe child");Mind actual=child;AtomicBoolean refused=new AtomicBoolean();Thread t=new Thread(()->{try{attempt.validate(actual);}catch(Exception expected){refused.set(true);}});t.start();t.join();require(refused.get(),"owner thread required");attempt.validate(actual);attempt.validate(actual);require(true,"same qualified actual child reused only while both baseline and live lease are current");require(child.compile("!changed(7);",null,false),"child mutation");ContextSignedCommitException stale=null;try{attempt.validate(actual);}catch(ContextSignedCommitException e){stale=e;}require(stale!=null&&stale.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&stale.getSignedEvidence()==null,"post-qualification child mutation invalidates retained permission");reject(()->attempt.validate(actual),"failed attempt cannot retry");}finally{if(child!=null)f.mind.release(child);f.db.endNativeWrite(attempt);}reject(()->attempt.validate(f.mind),"closed attempt");Mind retained=new Mind(f.mind);f.user.setCurrentMind(retained);try{reject(()->f.db.writeSignedProductionCandidate(retained,"!fresh(1);",limits(),WORK,WORK,1000000,false),"standalone writer cannot borrow retained user child");}finally{f.user.setCurrentMind(f.mind);f.mind.release(retained);}require(f.db.getRevision()==revision&&primary(f).size()==1,"ownership tests never settle parent");require(write(f,"!fresh(8);"),"fresh selected write succeeds after failed-attempt cleanup");}try(Fixture f=new Fixture(d,"X@"+revision)){require(f.db.isReadOnly(),"historical provider");reject(()->write(f,"!no(1);"),"read-only provider cannot select writable attempt");}System.out.println("SIGNED_SELECTED_WRITER_OWNERSHIP sameExactChildOnly=true nativeBaselineAndPendingCurrentness=true failedNoRetry=true mixedNestedRefusal=true historicalReadOnly=true");}
 static void boundary()throws Exception{Path d=Files.createTempDirectory("signed-writer-boundary-");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!local(1);",null,false),"actual baseline");long revision=f.db.getRevision();for(String text:new String[]{"","?local(1);","!one(1); !two(2);"})reject(()->write(f,text),"exact one assertion input");ContextSignedCommitException full=refused(f,"!bounded(1);",limits(),1,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(full.getPhase().equals("full-family-qualification")&&full.getSignedEvidence()==null,"public writer requires full-family work even without foreign contexts");ContextSignedCandidateInspection.Limits tiny=new ContextSignedCandidateInspection.Limits(64,8,2,16,WORK,500000,1,WORK,64);require(refused(f,"!bounded(1);",tiny,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE).getSignedEvidence()==null,"native work stop no proof prefix");refused(f,"!@u p(u)||q(u);",limits(),WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(f.db.getRevision()==revision&&primary(f).size()==1,"invalid and bounded attempts preserve physical state");require(!write(f,"!~local(1);"),"legacy local native conflict remains boolean false");require(f.db.getRevision()==revision&&primary(f).size()==1,"local native refusal unchanged");require(write(f,"!fresh(8);"),"no-connection safe publication and selection cleanup");require(primary(f).size()==2&&f.user.getCurrentMind()==f.mind&&f.user.getData()==f.db,"ordinary caller/provider preserved");}System.out.println("SIGNED_SELECTED_WRITER_BOUNDARY oneAssertion=true completeFamilyMandatory=true nativeFalseUnchanged=true noForeignStillQualified=true cleanup=true");}
}
